  Lemma Forall_blockish_lo : forall s L m X LF ff fp, as_RHEAP H s L m -> fresh_frame H LF 4 ff fp -> Forall (blockish L) X ->
    Forall (fun iv : Z * Z => fst iv < snd iv) X -> Forall (fun iv : Z * Z => AIMG_TOP <= fst iv /\ snd iv <= aceil) X.
  Proof.
    intros s L m X LF ff fp RH FF FB FL. induction X as [|iv X IH]; [apply Forall_nil|].
    apply Forall_cons; [| exact (IH (Forall_inv_tail FB) (Forall_inv_tail FL))].
    pose proof (blockish_facts _ _ _ _ _ _ _ RH FF (Forall_inv FB) (Forall_inv FL)) as (K1 & K2 & _). split; [exact K1| exact K2].
  Qed.
  Lemma Forall_blockish_fr : forall s L m X LF ff fp O n, as_RHEAP H s L m -> fresh_frame H LF 4 ff fp -> Forall (blockish L) X ->
    Forall (fun iv : Z * Z => fst iv < snd iv) X -> ff <= O -> O + n <= ff + 1024 ->
    Forall (fun iv : Z * Z => O + n <= fst iv \/ snd iv <= O) X.
  Proof.
    intros s L m X LF ff fp O n RH FF FB FL H1 H2. induction X as [|iv X IH]; [apply Forall_nil|].
    apply Forall_cons; [| exact (IH (Forall_inv_tail FB) (Forall_inv_tail FL))].
    pose proof (blockish_facts _ _ _ _ _ _ _ RH FF (Forall_inv FB) (Forall_inv FL)) as (_ & _ & K & _). lia.
  Qed.
  Lemma Forall_blockish_frsh : forall s L m X LF ff fp O n, as_RHEAP H s L m -> fresh_frame H LF 4 ff fp -> Forall (blockish L) X ->
    Forall (fun iv : Z * Z => fst iv < snd iv) X -> sh ff <= O -> O + n <= sh ff + 128 ->
    Forall (fun iv : Z * Z => O + n <= fst iv \/ snd iv <= O) X.
  Proof.
    intros s L m X LF ff fp O n RH FF FB FL H1 H2. induction X as [|iv X IH]; [apply Forall_nil|].
    apply Forall_cons; [| exact (IH (Forall_inv_tail FB) (Forall_inv_tail FL))].
    pose proof (blockish_facts _ _ _ _ _ _ _ RH FF (Forall_inv FB) (Forall_inv FL)) as (_ & _ & _ & K & _). lia.
  Qed.
  Lemma Forall_blockish_fp : forall s L m X LF ff fp, as_RHEAP H s L m -> fresh_frame H LF 4 ff fp -> Forall (blockish L) X ->
    Forall (fun iv : Z * Z => fst iv < snd iv) X -> Forall (fun iv : Z * Z => fp + 1 <= fst iv \/ snd iv <= fp) X.
  Proof.
    intros s L m X LF ff fp RH FF FB FL. induction X as [|iv X IH]; [apply Forall_nil|].
    apply Forall_cons; [| exact (IH (Forall_inv_tail FB) (Forall_inv_tail FL))].
    pose proof (blockish_facts _ _ _ _ _ _ _ RH FF (Forall_inv FB) (Forall_inv FL)) as (_ & _ & _ & _ & K). exact K.
  Qed.

  (* [comment removed for export] *)
  Definition hz_frame (m : mem) (spa ff fp spv allocb regb schedb stb : Z) (j24 j4 j16 j40 j32b j40b j392 : list byte) (gap saved shd : list cell) : Prop :=
       rw_cells bsegs m spa [CB 24 j24; C8 (Z_to_bv 64 ff)]
    /\ rw_cells bsegs m (spa + 32) (BasicStreamCells stb)
    /\ rw_cells bsegs m (spa + 64) gap /\ Z.of_nat (cells_size gap) = spv + -96 - (spa + 64)
    /\ rw_cells bsegs m (spv + -96) saved /\ Z.of_nat (cells_size saved) = 96
    /\ rw_cells bsegs m ff (hz_hdr spa ++ [C8 (Z_to_bv 64 AVP_CFGMAKER); C4 (wz 4294967295); CB 4 j4] ++ [CB 16 j16])
    /\ rw_cells bsegs m (ff + 88) [CB 40 j40]
    /\ rw_cells bsegs m (ff + 176) ([CB 32 j32b] ++ [C8 (Z_to_bv 64 allocb); C8 (Z_to_bv 64 regb); C8 (Z_to_bv 64 schedb)] ++ [CB 40 j40b])
    /\ rw_cells bsegs m (ff + 624) [CB 392 j392; C8 (Z_to_bv 64 fp)]
    /\ rw_cells bsegs m (Z.shiftr ff 3 + 2147450880) shd /\ Z.of_nat (cells_size shd) = 128
    /\ rw_cells bsegs m fp [C1 (b8 1)].

  (* [comment removed for export] *)
  Lemma hz_frame_keep : forall s0 L0 m00 s L m0 LF ff fp X XS m m' spa spv allocb regb schedb stb j24 j4 j16 j40 j32b j40b j392 gap saved shd,
    as_RHEAP H s0 L0 m00 -> as_RHEAP H s L m0 -> as_RFS H ((4, ff, fp) :: LF) m -> fresh_frame H LF 4 ff fp ->
    aceil <= spa -> spa + 160 <= spv ->
